* {
        margin: 0;
            padding: 0;
                box-sizing: border-box;
                }

                html {
                    scroll-behavior: smooth;
                    }

                    body {
                        font-family: Arial, sans-serif;
                            background: #f5f7fb;
                                color: #1f2937;
                                }


                                /* NAVBAR */

                                .navbar {
                                    position: sticky;
                                        top: 0;
                                            z-index: 100;

                                                display: flex;
                                                    justify-content: space-between;
                                                        align-items: center;

                                                            padding: 18px 8%;

                                                                background: white;

                                                                    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
                                                                    }

                                                                    .logo {
                                                                        font-size: 22px;
                                                                            font-weight: bold;
                                                                            }

                                                                            .logo span {
                                                                                color: #6366f1;
                                                                                }

                                                                                nav {
                                                                                    display: flex;
                                                                                        gap: 20px;
                                                                                        }

                                                                                        nav a {
                                                                                            text-decoration: none;
                                                                                                color: #374151;
                                                                                                    font-size: 14px;
                                                                                                        font-weight: 600;
                                                                                                        }

                                                                                                        nav a:hover {
                                                                                                            color: #6366f1;
                                                                                                            }


                                                                                                            /* HERO */

                                                                                                            .hero {
                                                                                                                min-height: 85vh;

                                                                                                                    display: flex;
                                                                                                                        align-items: center;
                                                                                                                            justify-content: center;

                                                                                                                                text-align: center;

                                                                                                                                    padding: 50px 20px;

                                                                                                                                        background: linear-gradient(
                                                                                                                                                135deg,
                                                                                                                                                        #eef2ff,
                                                                                                                                                                #ffffff
                                                                                                                                                                    );
                                                                                                                                                                    }

                                                                                                                                                                    .hero-content {
                                                                                                                                                                        max-width: 750px;
                                                                                                                                                                        }

                                                                                                                                                                        .tagline {
                                                                                                                                                                            color: #6366f1;
                                                                                                                                                                                font-size: 14px;
                                                                                                                                                                                    font-weight: bold;
                                                                                                                                                                                        letter-spacing: 2px;
                                                                                                                                                                                            margin-bottom: 20px;
                                                                                                                                                                                            }

                                                                                                                                                                                            .hero h1 {
                                                                                                                                                                                                font-size: clamp(45px, 8vw, 75px);
                                                                                                                                                                                                    line-height: 1.05;
                                                                                                                                                                                                        margin-bottom: 25px;
                                                                                                                                                                                                        }

                                                                                                                                                                                                        .hero h1 span {
                                                                                                                                                                                                            color: #6366f1;
                                                                                                                                                                                                            }

                                                                                                                                                                                                            .description {
                                                                                                                                                                                                                max-width: 600px;
                                                                                                                                                                                                                    margin: auto;

                                                                                                                                                                                                                        line-height: 1.7;
                                                                                                                                                                                                                            color: #6b7280;

                                                                                                                                                                                                                                font-size: 17px;
                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                button {
                                                                                                                                                                                                                                    border: none;
                                                                                                                                                                                                                                        cursor: pointer;

                                                                                                                                                                                                                                            background: #6366f1;
                                                                                                                                                                                                                                                color: white;

                                                                                                                                                                                                                                                    padding: 12px 20px;

                                                                                                                                                                                                                                                        border-radius: 8px;

                                                                                                                                                                                                                                                            font-weight: bold;

                                                                                                                                                                                                                                                                transition: 0.3s;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                button:hover {
                                                                                                                                                                                                                                                                    transform: translateY(-2px);
                                                                                                                                                                                                                                                                        opacity: 0.9;
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                        #startBtn {
                                                                                                                                                                                                                                                                            margin-top: 30px;
                                                                                                                                                                                                                                                                                padding: 15px 30px;
                                                                                                                                                                                                                                                                                    font-size: 16px;
                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                    /* DASHBOARD */

                                                                                                                                                                                                                                                                                    .dashboard {
                                                                                                                                                                                                                                                                                        padding: 70px 8%;
                                                                                                                                                                                                                                                                                            background: white;
                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                            .dashboard h2,
                                                                                                                                                                                                                                                                                            .section h2 {
                                                                                                                                                                                                                                                                                                font-size: 32px;
                                                                                                                                                                                                                                                                                                    margin-bottom: 10px;
                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                    .cards {
                                                                                                                                                                                                                                                                                                        display: grid;

                                                                                                                                                                                                                                                                                                            grid-template-columns:
                                                                                                                                                                                                                                                                                                                    repeat(auto-fit, minmax(200px, 1fr));

                                                                                                                                                                                                                                                                                                                        gap: 20px;

                                                                                                                                                                                                                                                                                                                            margin-top: 30px;
                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                            .card {
                                                                                                                                                                                                                                                                                                                                padding: 25px;

                                                                                                                                                                                                                                                                                                                                    background: #f8fafc;

                                                                                                                                                                                                                                                                                                                                        border-radius: 14px;

                                                                                                                                                                                                                                                                                                                                            border: 1px solid #e5e7eb;
                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                            .card-icon {
                                                                                                                                                                                                                                                                                                                                                font-size: 28px;
                                                                                                                                                                                                                                                                                                                                                    margin-bottom: 15px;
                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                    .card h3 {
                                                                                                                                                                                                                                                                                                                                                        font-size: 32px;
                                                                                                                                                                                                                                                                                                                                                            color: #6366f1;
                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                            .card p {
                                                                                                                                                                                                                                                                                                                                                                margin-top: 5px;
                                                                                                                                                                                                                                                                                                                                                                    color: #6b7280;
                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                    /* GENERAL SECTION */

                                                                                                                                                                                                                                                                                                                                                                    .section {
                                                                                                                                                                                                                                                                                                                                                                        padding: 80px 8%;
                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                        .section > p {
                                                                                                                                                                                                                                                                                                                                                                            color: #6b7280;
                                                                                                                                                                                                                                                                                                                                                                                margin-bottom: 30px;
                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                /* SKILLS */

                                                                                                                                                                                                                                                                                                                                                                                .skill-list {
                                                                                                                                                                                                                                                                                                                                                                                    max-width: 700px;
                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                    .skill {
                                                                                                                                                                                                                                                                                                                                                                                        display: flex;
                                                                                                                                                                                                                                                                                                                                                                                            justify-content: space-between;
                                                                                                                                                                                                                                                                                                                                                                                                align-items: center;

                                                                                                                                                                                                                                                                                                                                                                                                    background: white;

                                                                                                                                                                                                                                                                                                                                                                                                        padding: 18px;

                                                                                                                                                                                                                                                                                                                                                                                                            margin-bottom: 12px;

                                                                                                                                                                                                                                                                                                                                                                                                                border-radius: 10px;

                                                                                                                                                                                                                                                                                                                                                                                                                    border: 1px solid #e5e7eb;
                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                    .skill button {
                                                                                                                                                                                                                                                                                                                                                                                                                        padding: 8px 14px;
                                                                                                                                                                                                                                                                                                                                                                                                                            font-size: 13px;
                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                            /* COMPANY */

                                                                                                                                                                                                                                                                                                                                                                                                                            .company-form {
                                                                                                                                                                                                                                                                                                                                                                                                                                display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                    gap: 10px;

                                                                                                                                                                                                                                                                                                                                                                                                                                        max-width: 700px;
                                                                                                                                                                                                                                                                                                                                                                                                                                            margin-bottom: 25px;
                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                            .company-form input {
                                                                                                                                                                                                                                                                                                                                                                                                                                                flex: 1;

                                                                                                                                                                                                                                                                                                                                                                                                                                                    padding: 13px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                        border: 1px solid #d1d5db;

                                                                                                                                                                                                                                                                                                                                                                                                                                                            border-radius: 8px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                outline: none;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                .company {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        justify-content: space-between;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            align-items: center;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                max-width: 700px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: white;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: 18px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            margin-bottom: 10px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                border-radius: 10px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    border: 1px solid #e5e7eb;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    /* TASKS */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .task-list {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        max-width: 700px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .task {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                justify-content: space-between;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    align-items: center;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        background: white;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            padding: 18px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                margin-bottom: 12px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    border-radius: 10px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        border: 1px solid #e5e7eb;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        /* FOOTER */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        footer {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            text-align: center;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: 35px 20px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: #111827;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        color: white;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            line-height: 1.8;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            /* MOBILE */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            @media (max-width: 600px) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .navbar {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: 15px 5%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                nav {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        gap: 10px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                nav a {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        font-size: 11px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .hero {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        min-height: 75vh;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .section,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .dashboard {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            padding: 55px 5%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .company-form {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            flex-direction: column;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .skill,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .task,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .company {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    gap: 15px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        /* PROFILE CARD */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .profile-card {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                justify-content: space-between;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    align-items: center;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        gap: 20px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            padding: 25px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                margin: 25px 0 30px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: white;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        border-radius: 15px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            border: 1px solid #e5e7eb;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                box-shadow: 0 5px 20px rgba(0, 0, 0, 0.05);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .profile-info {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        align-items: center;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            gap: 18px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .profile-avatar {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                width: 65px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    height: 65px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                justify-content: center;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: #eef2ff;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        border-radius: 50%;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            font-size: 32px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .profile-info h3 {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                font-size: 22px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    margin-bottom: 5px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .profile-info p {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        color: #6b7280;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            margin: 3px 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            /* PROFILE MODAL */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .modal {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                display: none;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    position: fixed;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        z-index: 1000;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            left: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                top: 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    width: 100%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        height: 100%;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            background: rgba(0, 0, 0, 0.6);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    justify-content: center;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: 20px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .modal-content {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            position: relative;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                width: 100%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    max-width: 450px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        background: white;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            padding: 30px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                border-radius: 15px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    box-shadow: 0 15px 40px rgba(0, 0, 0, 0.2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .modal-content h2 {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        margin-bottom: 20px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .modal-content label {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            display: block;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                margin-top: 15px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    margin-bottom: 6px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        font-weight: bold;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            font-size: 14px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .modal-content input,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .modal-content select {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                width: 100%;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    padding: 12px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        border: 1px solid #d1d5db;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            border-radius: 8px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                outline: none;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-size: 15px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .modal-content > button:last-child {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        width: 100%;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            margin-top: 25px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: 13px;
